#!/usr/bin/env python3
"""Writes tx81z/tx81z.h (param table and presets are generated so the 32 per-operator parameters stay consistent)."""
import os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HEAD = r'''/*
 * tx81z.h - TX81Z style 4-operator FM synth: eight algorithms, eight operator waveforms,
 * frequency ratio and fine tune per operator, an ADSR per operator, feedback on operator 4,
 * LFO to pitch and amplitude, velocity. 8 voices. Original presets. Generated by tools/gen_tx81z.py.
 * Operators are numbered 1 to 4. Operator 1 is a carrier in every algorithm.
 */
#ifndef TX81Z_H
#define TX81Z_H
#include "synthcore.h"

#define TX_OP(n) ((n) * 8)   /* per-operator block of 8: ratio fine wave level attack decay sustain release */
enum { TX_ALGO = 32, TX_FB, TX_LFORATE, TX_LFOPM, TX_LFOAM, TX_VEL, TX_VOL, TX_COUNT };
enum { TO_RATIO, TO_FINE, TO_WAVE, TO_LEVEL, TO_A, TO_D, TO_S, TO_R };

static const float tx_ratio_tab[16] = { 0.5f, 0.71f, 0.78f, 0.87f, 1.0f, 1.41f, 1.57f, 1.73f, 2.0f, 2.82f, 3.0f, 3.14f, 3.46f, 4.0f, 5.0f, 7.0f };

'''
def opparams(n):
    lv = "0.8f" if n == 1 else "0.4f"
    return ('    {"ratio%(n)d", 4, 16}, {"fine%(n)d", 0.5f, 0}, {"wave%(n)d", 0, 8}, {"level%(n)d", %(lv)s, 0}, '
            '{"att%(n)d", 0.0f, 0}, {"dec%(n)d", 0.4f, 0}, {"sus%(n)d", 0.6f, 0}, {"rel%(n)d", 0.3f, 0},\n') % {"n": n, "lv": lv}
def op(n, ratio=4, fine=0.5, wave=0, level=0.5, att=0.0, dec=0.4, sus=0.6, rel=0.3):
    return "ratio%d=%d fine%d=%g wave%d=%d level%d=%g att%d=%g dec%d=%g sus%d=%g rel%d=%g" % (n, ratio, n, fine, n, wave, n, level, n, att, n, dec, n, sus, n, rel)
def pre(name, algo, fb, ops_, extra=""):
    return '    {"%s", "algo=%d feedback=%g %s %s"},\n' % (name, algo, fb, " ".join(ops_), extra)
PRESETS = [
 pre("Soft Keys",0,0.1,[op(1,4,0.5,0,0.9,0,0.6,0.1,0.35),op(2,4,0.5,0,0.45,0,0.4,0.05,0.3),op(3,4,0.5,0,0.3,0,0.3,0.0,0.3),op(4,4,0.5,0,0.2,0,0.3,0,0.3)]),
 pre("Tine Piano",1,0.15,[op(1,4,0.5,0,0.9,0,0.7,0.1,0.35),op(2,8,0.5,0,0.4,0,0.35,0.0,0.3),op(3,4,0.5,0,0.3,0,0.3,0,0.3),op(4,13,0.5,0,0.25,0,0.2,0,0.2)]),
 pre("Glass Bell",0,0.0,[op(1,4,0.5,0,0.9,0,0.9,0,0.9),op(2,9,0.5,0,0.55,0,0.8,0,0.8),op(3,4,0.5,0,0.2,0,0.3,0,0.3),op(4,9,0.5,0,0.2,0,0.3,0,0.3)]),
 pre("Marimba",4,0.0,[op(1,4,0.5,0,0.9,0,0.35,0,0.2),op(2,13,0.5,0,0.45,0,0.15,0,0.1),op(3,4,0.5,0,0.5,0,0.25,0,0.2),op(4,4,0.5,0,0.3,0,0.2,0,0.2)]),
 pre("Brass Stab",0,0.3,[op(1,4,0.5,0,0.9,0.05,0.6,0.6,0.25),op(2,4,0.5,0,0.5,0.1,0.45,0.35,0.25),op(3,4,0.5,0,0.4,0.05,0.4,0.2,0.2),op(4,4,0.5,0,0.3,0,0.3,0.2,0.2)]),
 pre("Slap Bass",0,0.25,[op(1,4,0.5,0,0.9,0,0.45,0.2,0.2),op(2,4,0.5,0,0.6,0,0.2,0,0.2),op(3,8,0.5,1,0.35,0,0.15,0,0.15),op(4,4,0.5,0,0.3,0,0.2,0,0.2)]),
 pre("Digi Strings",7,0.0,[op(1,4,0.5,6,0.6,0.55,0.5,0.9,0.7),op(2,4,0.52,6,0.55,0.55,0.5,0.9,0.7),op(3,4,0.48,6,0.55,0.55,0.5,0.9,0.7),op(4,4,0.5,6,0.5,0.6,0.5,0.9,0.7)]),
 pre("Organ Mix",7,0.0,[op(1,4,0.5,0,0.8,0,0.2,1,0.1),op(2,8,0.5,0,0.7,0,0.2,1,0.1),op(3,13,0.5,0,0.5,0,0.2,1,0.1),op(4,10,0.5,0,0.4,0,0.2,1,0.1)]),
 pre("Clav",2,0.2,[op(1,4,0.5,0,0.9,0,0.35,0.15,0.15),op(2,8,0.5,1,0.45,0,0.2,0,0.15),op(3,4,0.5,0,0.3,0,0.25,0,0.2),op(4,9,0.5,0,0.3,0,0.2,0,0.2)]),
 pre("Vibes",0,0.0,[op(1,4,0.5,0,0.9,0,0.8,0,0.7),op(2,13,0.5,0,0.3,0,0.35,0,0.5),op(3,4,0.5,0,0.2,0,0.3,0,0.3),op(4,4,0.5,0,0.2,0,0.3,0,0.3)],"lforate=0.25 lfoam=0.35"),
 pre("Breath Flute",0,0.55,[op(1,4,0.5,0,0.9,0.15,0.4,0.8,0.25),op(2,4,0.5,0,0.25,0.2,0.4,0.6,0.25),op(3,4,0.5,0,0.2,0.1,0.4,0.5,0.25),op(4,4,0.5,0,0.45,0.2,0.4,0.5,0.25)],"lforate=0.3 lfopm=0.12"),
 pre("Pluck Harp",4,0.0,[op(1,4,0.5,0,0.9,0,0.5,0,0.3),op(2,8,0.5,0,0.4,0,0.2,0,0.15),op(3,4,0.5,0,0.8,0,0.45,0,0.3),op(4,13,0.5,0,0.3,0,0.15,0,0.1)]),
 pre("Square Lead",0,0.4,[op(1,4,0.5,6,0.9,0,0.4,0.8,0.2),op(2,4,0.5,0,0.4,0,0.4,0.5,0.2),op(3,4,0.5,0,0.2,0,0.4,0,0.2),op(4,4,0.5,0,0.4,0,0.4,0.5,0.2)],"lforate=0.4 lfopm=0.1"),
 pre("Metal Hit",5,0.5,[op(1,5,0.5,0,0.9,0,0.35,0,0.35),op(2,11,0.5,4,0.65,0,0.3,0,0.3),op(3,12,0.5,0,0.6,0,0.25,0,0.25),op(4,14,0.5,5,0.5,0,0.2,0,0.2)]),
 pre("Warm Pad",1,0.1,[op(1,4,0.5,0,0.8,0.6,0.8,0.8,0.8),op(2,4,0.53,0,0.3,0.6,0.8,0.7,0.8),op(3,4,0.47,0,0.25,0.6,0.8,0.7,0.8),op(4,4,0.5,0,0.2,0.6,0.8,0.7,0.8)],"lforate=0.15 lfopm=0.04"),
 pre("Half Sine Bell",0,0.0,[op(1,4,0.5,1,0.85,0,0.7,0,0.6),op(2,10,0.5,2,0.5,0,0.6,0,0.5),op(3,4,0.5,0,0.2,0,0.3,0,0.3),op(4,4,0.5,3,0.3,0,0.3,0,0.3)]),
]
VOICE = r'''
static const unsigned char tx_mod[8][4] = {   /* bit k set: operator k+1 feeds this operator */
    { 2, 4, 8, 0 }, { 2, 12, 0, 0 }, { 6, 0, 8, 0 }, { 2, 4, 0, 0 },
    { 2, 0, 8, 0 }, { 8, 8, 8, 0 }, { 0, 0, 8, 0 }, { 0, 0, 0, 0 } };
static const unsigned char tx_car[8] = { 1, 1, 1, 9, 5, 7, 7, 15 };   /* bit k set: operator k+1 is a carrier */

static inline float tx_wave(int w, float ph)
{
    float s = sinf(6.2831853f * ph);
    switch (w) {
    case 0: return s;
    case 1: return s > 0.0f ? s : 0.0f;                                      /* half sine */
    case 2: return fabsf(s);                                                 /* full rectified */
    case 3: return fmodf(ph, 0.5f) < 0.25f ? fabsf(s) : 0.0f;                /* quarter pulses */
    case 4: return ph < 0.5f ? sinf(12.5663706f * ph) : 0.0f;                /* double speed half */
    case 5: return ph < 0.5f ? fabsf(sinf(12.5663706f * ph)) : 0.0f;
    case 6: return ph < 0.5f ? 1.0f : -1.0f;                                 /* square */
    default: return (ph < 0.5f ? 1.0f : -1.0f) * (1.0f - 2.0f * fmodf(ph, 0.5f));  /* decaying square */
    }
}

typedef struct { sk_env env[4]; float ph[4], fb1, fb2, lph, vel; int note; } tx_voice;

static void tx_vinit(void *vv, float sr) { tx_voice *v = (tx_voice *)vv; (void)sr; memset(v, 0, sizeof *v); for (int k = 0; k < 4; k++) sk_env_init(&v->env[k]); }
static void tx_von(void *vv, const float *p, int note, float vel, int first, float sr)
{
    tx_voice *v = (tx_voice *)vv; (void)p; (void)first; (void)sr;
    v->note = note; v->vel = vel; v->lph = 0.0f; v->fb1 = v->fb2 = 0.0f;
    for (int k = 0; k < 4; k++) { v->ph[k] = 0.0f; sk_env_on(&v->env[k], 1); }
}
static void tx_voff(void *vv, const float *p) { tx_voice *v = (tx_voice *)vv; (void)p; for (int k = 0; k < 4; k++) sk_env_off(&v->env[k]); }

static int tx_vrender(void *vv, const float *p, const sk_glob *g, float *out, int n)
{
    tx_voice *v = (tx_voice *)vv; float sr = g->sr;
    int algo = SK_SW(p, TX_ALGO, 8), ncar = 0, wave[4]; float inc[4], amp[4], velamt = p[TX_VEL];
    for (int k = 0; k < 4; k++) {
        const float *q = p + TX_OP(k);
        int ri = SK_SW(q, TO_RATIO, 16); wave[k] = SK_SW(q, TO_WAVE, 8);
        float semi = (q[TO_FINE] - 0.5f) * 1.0f;
        inc[k] = tx_ratio_tab[ri] * sk_mtof((float)v->note + g->bend + semi) / sr;
        float lv = q[TO_LEVEL]; amp[k] = lv < 0.003f ? 0.0f : expf((lv - 1.0f) * 5.5f);
        sk_env_set(&v->env[k], 0.0015f * powf(2000.0f, q[TO_A]), 0.004f * powf(1500.0f, q[TO_D]), q[TO_S], 0.004f * powf(1500.0f, q[TO_R]), sr);
        if (tx_car[algo] & (1 << k)) ncar++;
    }
    float outg = 0.9f / sqrtf((float)(ncar > 0 ? ncar : 1)) * p[TX_VOL] * 1.6f;
    float fb = p[TX_FB] * 0.6f, vs = 1.0f - velamt * (1.0f - v->vel);
    float lr = sk_expmap(p[TX_LFORATE], 0.1f, 20.0f), lpm = p[TX_LFOPM] * p[TX_LFOPM] * 0.5f * (1.0f + g->mod), lam = p[TX_LFOAM];
    int alive = 0;
    for (int i = 0; i < n; i++) {
        float e[4], o[4] = { 0, 0, 0, 0 };
        for (int k = 0; k < 4; k++) { e[k] = sk_env_tick(&v->env[k]); if (v->env[k].st != SK_ENV_IDLE) alive = 1; }
        v->lph += lr / sr; if (v->lph >= 1.0f) v->lph -= 1.0f;
        float l = v->lph < 0.5f ? 4.0f * v->lph - 1.0f : 3.0f - 4.0f * v->lph;
        float pm = 1.0f + l * lpm * 0.06f, am = 1.0f - lam * 0.5f * (1.0f + l);
        float sum = 0.0f;
        for (int k = 3; k >= 0; k--) {
            float m = 0.0f; unsigned mask = tx_mod[algo][k];
            for (int j = 0; j < 4; j++) if (mask & (1u << j)) m += o[j];
            if (k == 3) m += fb * 0.5f * (v->fb1 + v->fb2);
            v->ph[k] += inc[k] * pm; if (v->ph[k] >= 1.0f) v->ph[k] -= 1.0f;
            float ph = v->ph[k] + m * 1.2f; ph -= floorf(ph);
            o[k] = tx_wave(wave[k], ph) * amp[k] * e[k] * vs;
            if (k == 3) { v->fb2 = v->fb1; v->fb1 = o[3]; }
            if (tx_car[algo] & (1 << k)) sum += o[k];
        }
        out[i] += sum * outg * am;
    }
    return alive;
}

static const sk_def tx_def = {
    "tx81z", TX_COUNT, tx_params, (int)(sizeof tx_presets / sizeof tx_presets[0]), tx_presets,
    8, 0, -1, sizeof(tx_voice), 0,
    tx_vinit, tx_von, tx_voff, tx_vrender, 0, 0
};
#endif
'''
pt = "static const sk_param tx_params[TX_COUNT] = {\n" + "".join(opparams(n) for n in range(1, 5))
pt += '    {"algo", 0, 8}, {"feedback", 0.0f, 0}, {"lforate", 0.3f, 0}, {"lfopm", 0.0f, 0}, {"lfoam", 0.0f, 0}, {"vel", 0.5f, 0}, {"vol", 0.7f, 0},\n};\n\n'
os.makedirs(os.path.join(ROOT, "tx81z"), exist_ok=True)
open(os.path.join(ROOT, "tx81z", "tx81z.h"), "w").write(HEAD + pt + "static const sk_preset_def tx_presets[] = {\n" + "".join(PRESETS) + "};\n" + VOICE)
open(os.path.join(ROOT, "tx81z", "tx81z~.c"), "w").write('/* tx81z~ - TX81Z style 4-operator FM synth. See tx81z.h and synthwrap.h. */\n#include "tx81z.h"\n#include "synthwrap.h"\nSK_PD_CLASS(tx81z, "tx81z~", tx_def)\n')
print("wrote tx81z")
